const EXPANDED_RULE_KEYS = ["rules.expanded.title", "rules.expanded.chapter_01.title", "rules.expanded.chapter_01.paragraph_01", "rules.expanded.chapter_01.paragraph_02", "rules.expanded.chapter_01.civilian_goal", "rules.expanded.chapter_01.impostor_goal", "rules.expanded.chapter_02.title", "rules.expanded.chapter_02.item_01", "rules.expanded.chapter_02.item_02", "rules.expanded.chapter_02.item_03", "rules.expanded.chapter_02.item_04", "rules.expanded.chapter_02.live_mode", "rules.expanded.chapter_02.chat_mode", "rules.expanded.chapter_02.paragraph_01", "rules.expanded.chapter_03.title", "rules.expanded.chapter_03.paragraph_01", "rules.expanded.chapter_03.paragraph_02", "rules.expanded.chapter_03.paragraph_03", "rules.expanded.chapter_03.paragraph_04", "rules.expanded.chapter_04.title", "rules.expanded.chapter_04.paragraph_01", "rules.expanded.chapter_04.example", "rules.expanded.chapter_04.warning", "rules.expanded.chapter_04.paragraph_02", "rules.expanded.chapter_04.duration_intro", "rules.expanded.chapter_04.duration_01", "rules.expanded.chapter_04.duration_02", "rules.expanded.chapter_04.duration_03", "rules.expanded.chapter_05.title", "rules.expanded.chapter_05.paragraph_01", "rules.expanded.chapter_05.paragraph_02", "rules.expanded.chapter_05.prediction_intro", "rules.expanded.chapter_05.item_01", "rules.expanded.chapter_05.item_02", "rules.expanded.chapter_05.item_03", "rules.expanded.chapter_05.item_04", "rules.expanded.chapter_05.item_05", "rules.expanded.chapter_05.important", "rules.expanded.chapter_06.title", "rules.expanded.chapter_06.paragraph_01", "rules.expanded.chapter_06.paragraph_02", "rules.expanded.chapter_06.paragraph_03", "rules.expanded.chapter_06.outcomes_title", "rules.expanded.chapter_06.outcome_01", "rules.expanded.chapter_06.outcome_02", "rules.expanded.chapter_06.outcome_03", "rules.expanded.chapter_06.outcome_04", "rules.expanded.remember.title", "rules.expanded.remember.item_01", "rules.expanded.remember.item_02", "rules.expanded.closing"];
const sourceToKey = new Map(Object.entries(UI_PACKS.source).map(([key, text]) => [text, key]));
let uiLanguage = detectUiLanguage();
const listeners = new Set();

function detectUiLanguage() {
  const saved = localStorage.getItem(UI_STORAGE_KEY);
  if (UI_LANGS.includes(saved)) return saved;
  const preferred = navigator.languages?.length ? navigator.languages : [navigator.language || ""];
  for (const item of preferred) {
    const base = String(item || "").toLowerCase().split("-")[0];
    if (UI_LANGS.includes(base)) return base;
  }
  return "hr";
}

function t(key, params) {
  const pack = UI_PACKS[uiLanguage] || UI_PACKS.hr;
  let text = pack[key] ?? UI_PACKS.hr[key] ?? key;
  if (params) {
    for (const [name, value] of Object.entries(params)) {
      text = text.split("{" + name + "}").join(String(value ?? ""));
    }
  }
  return text;
}

function modeLabel(mode) {
  return mode === "chat" ? t("mode.chat") : t("mode.live");
}

function hasSavedLanguage() {
  return UI_LANGS.includes(localStorage.getItem(UI_STORAGE_KEY));
}

function tFor(lang, key, params) {
  const pack = UI_PACKS[lang] || UI_PACKS.hr;
  let text = pack[key] ?? UI_PACKS.hr[key] ?? key;
  if (params) {
    for (const [name, value] of Object.entries(params)) {
      text = text.split("{" + name + "}").join(String(value ?? ""));
    }
  }
  return text;
}

function translateServerMessage(message) {
  const text = String(message || "");
  const key = sourceToKey.get(text);
  if (key === "api.mode_locked" || text.startsWith("Host je napravio ") && text.endsWith(" sobu.")) {
    const mode = text.includes("Chat") ? "chat" : "live";
    return t("api.mode_locked", { mode: modeLabel(mode) });
  }
  return key ? t(key) : text;
}

function applyStaticTranslations() {
  document.documentElement.lang = uiLanguage;
  document.title = t("meta.document_title");
  document.querySelectorAll("[data-i18n]").forEach((node) => {
    node.textContent = t(node.dataset.i18n);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((node) => {
    node.placeholder = t(node.dataset.i18nPlaceholder);
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((node) => {
    node.setAttribute("aria-label", t(node.dataset.i18nAria));
  });
  document.querySelectorAll("[data-lang]").forEach((button) => {
    const selected = button.dataset.lang === uiLanguage;
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-pressed", selected ? "true" : "false");
  });
  document.querySelector("#languageMenuButton")?.setAttribute("aria-label", t("language.selector.aria_label"));
  const homeLogo = document.querySelector("#homeLogo");
  if (homeLogo) {
    const files = { sr: "Varalica_home.png", hr: "Varalica_home.png", de: "Betrüger_home.png", tr: "Sahtekar_home.png" };
    const file = files[uiLanguage] || files.hr;
    homeLogo.src = "/static/assets/" + encodeURIComponent(file) + "?v=20261122_6";
    homeLogo.alt = t("home.title");
    homeLogo.classList.toggle("is-varalica", uiLanguage === "sr" || uiLanguage === "hr");
  }
}

function setUiLanguage(lang, { manual = false } = {}) {
  if (!UI_LANGS.includes(lang)) return;
  uiLanguage = lang;
  if (manual) localStorage.setItem(UI_STORAGE_KEY, lang);
  applyStaticTranslations();
  listeners.forEach((listener) => listener(lang));
}

function onUiLanguageChange(listener) {
  listeners.add(listener);
}

applyStaticTranslations();
window.VaralicaI18n = {
  t,
  tFor,
  modeLabel,
  translateServerMessage,
  setUiLanguage,
  onUiLanguageChange,
  hasSavedLanguage,
  expandedRuleKeys: EXPANDED_RULE_KEYS,
  get language() {
    return uiLanguage;
  },
};
